const safeInherited = process.env.ODEN_CHILD_SAFE_SENTINEL === "safe";
const controlPlaneHidden = Object.keys(process.env).every((key) =>
  !key.startsWith("ODEN_CAPSEC_")
);
const nodeOptions = process.env.NODE_OPTIONS || "";
const inheritedNodeOptions = nodeOptions.includes("--trace-warnings");
const translatedNodeOptions = nodeOptions.includes("--no-warnings");
const opensslCaRemoved = process.env.DENO_NODE_USE_OPENSSL_CA === undefined;

process.exitCode = !safeInherited
  ? 11
  : !controlPlaneHidden
  ? 12
  : !inheritedNodeOptions
  ? 13
  : !translatedNodeOptions
  ? 15
  : !opensslCaRemoved
  ? 14
  : 0;
